CREATE OR REPLACE FUNCTION public.is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('admin','owner')) $$;
CREATE OR REPLACE FUNCTION public.my_permissions() RETURNS SETOF text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH role_perms AS (SELECT rp.permission_key AS k FROM public.user_roles ur JOIN public.role_permissions rp ON (rp.role_key=ur.role::text OR (ur.role='owner' AND rp.role_key='admin')) WHERE ur.user_id=auth.uid()), active_overrides AS (SELECT permission_key AS k,granted FROM public.user_permission_overrides WHERE user_id=auth.uid() AND (expires_at IS NULL OR expires_at>now())), granted AS (SELECT k FROM role_perms UNION SELECT k FROM active_overrides WHERE granted=true), denied AS (SELECT k FROM active_overrides WHERE granted=false) SELECT DISTINCT k FROM granted WHERE k NOT IN(SELECT k FROM denied) $$;
CREATE OR REPLACE FUNCTION public.has_permission(_user_id uuid,_permission_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH active_overrides AS (SELECT granted FROM public.user_permission_overrides WHERE user_id=_user_id AND permission_key=_permission_key AND (expires_at IS NULL OR expires_at>now())) SELECT CASE WHEN EXISTS(SELECT 1 FROM active_overrides WHERE granted=false) THEN false WHEN EXISTS(SELECT 1 FROM active_overrides WHERE granted=true) THEN true ELSE EXISTS(SELECT 1 FROM public.user_roles ur JOIN public.role_permissions rp ON (rp.role_key=ur.role::text OR (ur.role='owner' AND rp.role_key='admin')) WHERE ur.user_id=_user_id AND rp.permission_key=_permission_key) END $$;
ALTER POLICY "Admins can write settings" ON public.app_settings USING(public.is_admin()) WITH CHECK(public.is_admin());
ALTER POLICY "Admins can delete booking charges" ON public.booking_charges USING(public.is_admin());
ALTER POLICY "roles admin write" ON public.roles USING(public.is_admin()) WITH CHECK(public.is_admin());
ALTER POLICY "permissions admin write" ON public.permissions USING(public.is_admin()) WITH CHECK(public.is_admin());
ALTER POLICY "rp admin write" ON public.role_permissions USING(public.is_admin()) WITH CHECK(public.is_admin());
ALTER POLICY "Admins can hard delete guest documents" ON public.guest_documents USING(public.is_admin());
CREATE OR REPLACE FUNCTION public.sweep_abandoned_leads() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_minutes int; n int; BEGIN SELECT COALESCE((value->>'abandon_minutes')::int,5) INTO v_minutes FROM public.app_settings WHERE key='crm'; IF v_minutes IS NULL OR v_minutes<=0 THEN v_minutes:=5; END IF; WITH upd AS(UPDATE public.leads SET status='Abandoned',abandoned_at=now() WHERE status='Interested' AND booking_id IS NULL AND last_activity_at<(now()-make_interval(mins=>v_minutes)) RETURNING 1) SELECT count(*) INTO n FROM upd; RETURN COALESCE(n,0); END $$;